DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `idNotification` int NOT NULL AUTO_INCREMENT,
  `recipientId` int NOT NULL,
  `recipientType` enum('USER','COMPANY') NOT NULL,
  `type` enum('COMMENT_REPORTED','COMMENT_REPLY','OFFER_COMMENT','OFFER_REPORTED','COMPANY_REPORTED') NOT NULL,
  `referenceId` int NOT NULL,
  `referenceType` enum('USER','COMPANY','OFFER','COMMENT') NOT NULL,
  `message` varchar(255) NOT NULL,
  `isRead` tinyint(1) DEFAULT '0',
  `createdAt` datetime DEFAULT (utc_timestamp()),
  `readAt` datetime DEFAULT NULL,
  PRIMARY KEY (`idNotification`),
  KEY `idx_recipient` (`recipientId`,`recipientType`,`isRead`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;
