CREATE TABLE `offers` (
  `idOffer` int NOT NULL AUTO_INCREMENT,
  `idCompany` int NOT NULL,
  `title` varchar(100) NOT NULL,
  `salaryMin` int NOT NULL,
  `salaryMax` int DEFAULT NULL,
  `description` text NOT NULL,
  `location` varchar(255) NOT NULL,
  `contractType` enum('MEDIO_TIEMPO','TIEMPO_COMPLETO','POR_HORAS','TEMPORAL') NOT NULL,
  `expireDate` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT (utc_timestamp()),
  PRIMARY KEY (`idOffer`),
  KEY `fk_Offers_Company1_idx` (`idCompany`),
  CONSTRAINT `fk_Offers_Company1` FOREIGN KEY (`idCompany`) REFERENCES `company` (`idCompany`),
  CONSTRAINT `chk_salary_range` CHECK ((`salaryMin` <= `salaryMax`))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb3;
