/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `Offers_AFTER_INSERT` AFTER INSERT ON `offers` FOR EACH ROW BEGIN
INSERT INTO Audit(
    actorId,
    actorType,

    action,

    entityType,
    entityId,

    oldValue,
    newValue,

    ipAddress,
    userAgent
)
VALUES(
    @audit_actor_id,
    IFNULL(
        @audit_actor_type,
        'SYSTEM'
    ),

    'INSERT',

    'OFFER',
    NEW.idOffer,

    NULL,

    JSON_OBJECT(
        'title', NEW.title,
        'salaryMin', NEW.salaryMin,
        'location', NEW.location,
        'description', NEW.description
    ),

    IFNULL(
        @audit_ip,
        'UNKNOWN'
    ),

    IFNULL(
        @audit_user_agent,
        'UNKNOWN'
    )
);
END */;;
