/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `Offers_AFTER_DELETE` AFTER DELETE ON `offers` FOR EACH ROW BEGIN
INSERT INTO Audit(
    actorId,
    actorType,

    action,

    entityType,
    entityId,

    oldValue,
    newValue,

    ipAddress,
    userAgent
)
VALUES(
    @audit_actor_id,
    IFNULL(
        @audit_actor_type,
        'SYSTEM'
    ),

    'DELETE',

    'OFFER',
    OLD.idOffer,

    JSON_OBJECT(
        'title', OLD.title,
        'salaryMin', OLD.salaryMin,
        'location', OLD.location,
        'description', OLD.description
    ),

    NULL,

    IFNULL(
        @audit_ip,
        'UNKNOWN'
    ),

    IFNULL(
        @audit_user_agent,
        'UNKNOWN'
    )
);
END */;;
