    @audit_actor_id,

    IFNULL(
        @audit_actor_type,
        'SYSTEM'
    ),

    'INSERT',

    'USER',

    NEW.idUser,

    NULL,

    JSON_OBJECT(
        'document', NEW.document,
        'name', NEW.name,
        'phone', NEW.phone
    ),

    IFNULL(
        @audit_ip,
        'UNKNOWN'
    ),

    IFNULL(
        @audit_user_agent,
        'UNKNOWN'
    )
);
